<title>Dragon's Double Take</title>
<style>
@font-face{font-family:Fredoka;src:url(data:font/ttf;base64,) format('truetype');font-weight:300 700;font-display:swap}
*{box-sizing:border-box} :root{color-scheme:dark;--plum:#352044;--ink:#f4eaf8;--mint:#a6e6bf;--coral:#ffb096;--quiet:#d4bfdf}
body{margin:0;background:var(--plum);color:var(--ink);font:17px/1.6 system-ui,sans-serif}
::selection{background:var(--mint);color:var(--plum)}:focus-visible{outline:3px solid var(--mint);outline-offset:5px}
a{color:var(--mint);text-underline-offset:4px} a:hover{color:white}
main{max-width:1160px;margin:auto;padding:25px 32px 55px}
nav{display:flex;justify-content:space-between;gap:15px;font-size:14px;margin-bottom:27px}nav span{color:var(--quiet)}nav a{min-height:44px;display:inline-flex;align-items:center}
h1,h2,button{font-family:Fredoka,system-ui,sans-serif}h1{font-size:clamp(2.5rem,6.3vw,5.7rem);font-weight:600;line-height:1.03;letter-spacing:-.025em;max-width:850px;margin:0 0 17px;text-wrap:balance}
