.experiment{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,1fr);gap:42px;align-items:center;margin:20px 0 45px}
.stage{min-width:0;position:relative}#dragon{width:100%;aspect-ratio:1;display:block;touch-action:pan-y;cursor:ew-resize;border-radius:50%} .stage p{text-align:center;font-size:14px;color:var(--quiet);margin:0}
