button.primary{background:var(--coral);color:var(--plum);border-color:var(--coral)}button.primary:hover{background:#ffc6b3}
button:disabled{opacity:.5;cursor:default}.small{font-size:14px;color:var(--quiet)}#status{min-height:52px;margin:15px 0;color:var(--mint)}
