<body>
<main>
<nav><a href="index.php">← Chloe Reads Jon</a><span>A small trick of perspective</span></nav>
<h1>Dragon's<br><span>double take.</span></h1>
<p class="intro">A hollow face can look like it is turning to watch you. Borrow this dragon's very questionable sense of personal space.</p>
<noscript><p>Turn on JavaScript to move the dragon and explore the illusion.</p></noscript>
<section class="experiment" aria-label="Interactive hollow-mask experiment">
<div class="stage">
<canvas id="dragon" aria-describedby="stageHint" width="700" height="700" role="img" aria-label="Painted dragon mapped onto a hollow surface. Use the viewpoint slider to move around it."></canvas>
<img id="fallback" alt="The original painted mint-green dragon face" src="data:image/webp;base64,">
<p id="stageHint">Move the slider, or drag across the dragon.</p>
</div>
<div class="controls">
<h2>Does it follow you?</h2>
<p class="small">Try the hollow face first. Look at its nose while moving slowly left and right.</p>
<div class="buttons" role="group" aria-label="Surface depth">
<button data-mode="hollow" aria-pressed="true">Hollow</button><button data-mode="solid" aria-pressed="false">Bulging</button><button data-mode="flat" aria-pressed="false">Flat</button>
</div>
<div class="range-label"><label for="view">Your viewpoint</label><output id="angle" for="view">Centre</output></div>
<input id="view" type="range" min="-40" max="40" step="1" value="0">
<div class="ends"><span>Walk left</span><span>Walk right</span></div>
<div class="buttons"><button id="tour" class="primary">Take a slow look</button><button id="centre">Re-centre</button></div>
<div class="buttons"><button id="mesh" aria-pressed="false">Reveal the mesh</button></div>
<p id="status" role="status" aria-live="polite">Hollow: the nose is behind the edges. Your brain may disagree.</p>
<div class="cutaway"><strong>The truth, from above</strong><canvas id="profile" width="700" height="200" role="img" aria-label="Cross-section: hollow face curves away from you."></canvas><p>The line is the real surface. The dot is your viewpoint, shown schematically.</p></div>
</div>
</section>
<section class="notes" aria-label="About the illusion">
<div><h2>A face-shaped assumption</h2><p>We are so used to faces bulging outwards that a painted hollow face can look solid instead. With that mistaken depth, its changing perspective can seem like a head turning towards you.</p><p class="small">This is a simplified digital hollow-mask demonstration, inspired by Jon's paper dragon. It works differently for different people. A flat screen, visible edges, and the mesh can all give the trick away.</p></div>
<div><h2>Catch your brain in the act</h2><p>Compare <strong>Hollow</strong> with <strong>Bulging</strong>. Then reveal the mesh. Same painting, different geometry. Does seeing the structure break the spell?</p>
<div class="observation"><div class="buttons"><button id="follows">It follows me!</button><button id="bowl">I see a bowl</button></div><p id="reaction" aria-live="polite" class="small">Both are honest answers. Dragons are unreliable lab assistants.</p></div>
</div>
</section>
<footer><p>Inspired by Jon's <a href="?source=1">Dragon Optical Illusion post</a> from November 2004.</p><p>Original dragon artwork generated for this experiment. No camera, motion sensors, or face tracking. The painting never changes.</p></footer>
</main>
<script>
'use strict';
const canvas=document.querySelector('#dragon'), view=document.querySelector('#view'), profile=document.querySelector('#profile');
const status=document.querySelector('#status'), angle=document.querySelector('#angle'),tour=document.querySelector('#tour');
const painting=new Image();painting.src='data:image/webp;base64,';
let mode='hollow',showMesh=false,raf=0,tourStart=0,gl,program,triBuffer,lineBuffer,tex;
const depth=()=>mode==='hollow'?-.65:mode==='solid'?.65:0;
function shape(x,y){return depth()*(1-x*x)*(1-y*y)}
function stopTour(){cancelAnimationFrame(raf);raf=0;tour.textContent='Take a slow look'}
function update(){
 const v=+view.value;angle.value=v===0?'Centre':Math.abs(v)+'° '+(v<0?'left':'right');
 canvas.setAttribute('aria-label',mode+' dragon face viewed from '+angle.value+'. '+(showMesh?'Surface mesh visible.':'Surface mesh hidden.'));
 draw();cutaway();
}
function cutaway(){
 const c=profile.getContext('2d'),w=profile.width,h=profile.height;
 c.clearRect(0,0,w,h);c.lineWidth=2;c.strokeStyle='#947ba3';c.beginPath();c.moveTo(70,65);c.lineTo(w-70,65);c.stroke();
 c.strokeStyle='#a6e6bf';c.lineWidth=5;c.beginPath();
 for(let i=0;i<=100;i++){let x=i/50-1,y=65+shape(x,0)*60;i?c.lineTo(70+i*(w-140)/100,y):c.moveTo(70,y)}c.stroke();
 const ex=w/2+(+view.value/40)*170;c.fillStyle='#ffb096';c.beginPath();c.arc(ex,171,9,0,Math.PI*2);c.fill();
 c.font='23px system-ui';c.textAlign='center';c.fillStyle='#f4eaf8';c.fillText('you',ex,199);c.textAlign='left';c.fillText(mode==='hollow'?'nose recedes':mode==='solid'?'nose projects':'no depth',75,29);
 profile.setAttribute('aria-label','Top-down cross-section: '+(mode==='hollow'?'nose curves away from you':mode==='solid'?'nose bulges towards you':'flat surface')+'. Your viewpoint is '+angle.value);
}
function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('Shader unavailable');return s}
function init(){
 try{
 gl=canvas.getContext('webgl',{alpha:true,antialias:true,preserveDrawingBuffer:true});if(!gl)throw Error('WebGL unavailable');
 program=gl.createProgram();
 gl.attachShader(program,shader(gl.VERTEX_SHADER,`attribute vec2 a;uniform float d;uniform float r;varying vec2 uv;void main(){float z=d*(1.0-a.x*a.x)*(1.0-a.y*a.y);float x=a.x*cos(r)-z*sin(r);float zz=a.x*sin(r)+z*cos(r);float distance=3.8-zz;gl_Position=vec4(x*2.8,a.y*2.8,0.1*distance,distance);uv=vec2((a.x+1.0)/2.0,(1.0-a.y)/2.0);}`));
 gl.attachShader(program,shader(gl.FRAGMENT_SHADER,`precision mediump float;varying vec2 uv;uniform sampler2D image;uniform bool lines;void main(){gl_FragColor=lines?vec4(0.98,0.89,0.98,1.0):texture2D(image,uv);}`));
 gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Renderer unavailable');gl.useProgram(program);
 const tris=[],lines=[],n=36;
 for(let j=0;j<n;j++)for(let i=0;i<n;i++){
 let x=-1+2*i/n,y=-1+2*j/n,X=x+2/n,Y=y+2/n;
 tris.push(x,y,X,y,X,Y,x,y,X,Y,x,Y);
 if(i%3===0)lines.push(x,y,x,Y);if(j%3===0)lines.push(x,y,X,y);
 }
 triBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,triBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(tris),gl.STATIC_DRAW);triBuffer.count=tris.length/2;
 lineBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,lineBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(lines),gl.STATIC_DRAW);lineBuffer.count=lines.length/2;
 tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,painting);
 gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
 update();
 }catch(e){fallback('The 3D view could not start here. The original dragon is below; the controls still show its cross-section.')}
}
function fallback(message){gl=null;canvas.style.display='none';document.querySelector('#fallback').style.display='block';document.querySelector('#stageHint').textContent=message;document.querySelector('#mesh').disabled=true;cutaway()}
function draw(){
 if(!gl||!program)return;
 const side=Math.round(canvas.clientWidth*Math.min(devicePixelRatio||1,2));if(canvas.width!==side){canvas.width=canvas.height=side}
 gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);
 gl.uniform1f(gl.getUniformLocation(program,'d'),depth());gl.uniform1f(gl.getUniformLocation(program,'r'),+view.value*Math.PI/180);
 const a=gl.getAttribLocation(program,'a');gl.enableVertexAttribArray(a);
 for(const [buffer,isLine] of [[triBuffer,false],[lineBuffer,true]]){if(isLine&&!showMesh)continue;gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);gl.uniform1i(gl.getUniformLocation(program,'lines'),isLine?1:0);gl.drawArrays(isLine?gl.LINES:gl.TRIANGLES,0,buffer.count)}
}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{
 stopTour();mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));
 status.textContent=mode==='hollow'?'Hollow: the nose is behind the edges. Your brain may disagree.':mode==='solid'?'Bulging: the nose projects towards you. Compare its movement with Hollow.':'Flat: a painted sheet with no nose depth. Watch its perspective change.';update();
}));
view.addEventListener('input',()=>{stopTour();update()});
document.querySelector('#centre').onclick=()=>{stopTour();view.value=0;update()};
document.querySelector('#mesh').onclick=e=>{showMesh=!showMesh;e.currentTarget.setAttribute('aria-pressed',String(showMesh));e.currentTarget.textContent=showMesh?'Hide the mesh':'Reveal the mesh';update()};
tour.onclick=()=>{
 if(raf){stopTour();return}
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){view.value=+view.value===-30?30:-30;update();status.textContent='Reduced motion: moved to a still viewpoint. Press again to compare the other side.';return}
 tourStart=performance.now();tour.textContent='Pause the look';
 function tick(t){let p=Math.min((t-tourStart)/6500,1);view.value=Math.round(35*Math.sin(p*Math.PI*2));update();if(p<1)raf=requestAnimationFrame(tick);else{stopTour();view.value=0;update()}}raf=requestAnimationFrame(tick)
};
let dragging=false;
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){dragging=true;canvas.setPointerCapture(e.pointerId)}else{dragging=true}stopTour()});
canvas.addEventListener('pointermove',e=>{if(!dragging)return;const b=canvas.getBoundingClientRect();view.value=Math.round(Math.max(-40,Math.min(40,(e.clientX-b.left)/b.width*80-40)));update()});
window.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);
document.querySelector('#follows').onclick=()=>{document.querySelector('#reaction').textContent='Caught it! Now try Bulging, then switch back to Hollow. Your eyes may keep arguing with the geometry.'};
document.querySelector('#bowl').onclick=()=>{document.querySelector('#reaction').textContent='You spotted the actual shape. Hide the mesh, return to centre, and focus on the nose. If it still looks hollow, that is fine too.'};
painting.onload=init;painting.onerror=()=>fallback('The dragon painting did not load. Reload to try again; the cross-section still works.');
if(painting.complete&&painting.naturalWidth)init();
new ResizeObserver(()=>draw()).observe(canvas);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour()});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();stopTour();fallback('The 3D view paused. Reload to restore it; the cross-section still works.')});update();
</script></body></html>